mapper.select:
SELECT p.*, g.name as game_name, g.icon as game_icon, u.nickname, u.avatar as user_avatar, u.ex1 as user_level, CASE WHEN p.likes_user IS NULL OR p.likes_user = '' THEN 0 ELSE (LENGTH(p.likes_user) - LENGTH(REPLACE(p.likes_user, ',', '')) + 1) END as likes, CASE WHEN p.favorites_user IS NULL OR p.favorites_user = '' THEN 0 ELSE (LENGTH(p.favorites_user) - LENGTH(REPLACE(p.favorites_user, ',', '')) + 1) END as favorites FROM t_post p LEFT JOIN t_game g ON p.game_id = g.id LEFT JOIN t_user_info u ON p.user_id = u.user_id
p.deleted = 0
AND p.title LIKE CONCAT('%', #{dto.title}, '%')
AND ( p.title LIKE CONCAT('%', #{dto.keyword}, '%') OR p.content LIKE CONCAT('%', #{dto.keyword}, '%') OR p.topics LIKE CONCAT('%', #{dto.keyword}, '%') OR g.name LIKE CONCAT('%', #{dto.keyword}, '%') )
AND p.topics LIKE CONCAT('%', #{dto.topic}, '%')
AND p.game_id = #{dto.gameId}
AND p.audit_status = #{dto.auditStatus}
AND p.appeal_status = #{dto.appealStatus}
AND p.create_time >= #{dto.startTime}
AND p.create_time <= #{dto.endTime}
ORDER BY p.create_time DESC
